// Part 9: More exam topics, units 73-77. See materials/curriculum.md and materials/objectives/.
// p9Fixture() adds the small settings files the terminal exercises read: locale, time zone, mail aliases, a .gitignore and an nginx site.
function p9Fixture() {
  const fx = homeFixture();
  fx.dirs.push('/etc/default', '/etc/nginx', '/etc/nginx/sites-available', '/home/user/shop');
  fx.files.push(
    ['/etc/default/locale', { owner: 'root', content: 'LANG=en_US.UTF-8\nLC_TIME=he_IL.UTF-8\n' }],
    ['/etc/timezone', { owner: 'root', content: 'Asia/Jerusalem\n' }],
    ['/etc/aliases', { owner: 'root', content: '# See man 5 aliases for format\npostmaster:    root\nroot: dana\nadmin: dana\nwebmaster: dana, omer\n' }],
    ['/home/user/shop/.gitignore', { content: '*.log\n.env\nnode_modules/\n' }],
    ['/etc/nginx/sites-available/shop', { owner: 'root', content: 'server {\n    listen 80;\n    server_name shop.example.com;\n    root /var/www/shop;\n}\n' }],
  );
  return fx;
}
const p9Out = cmd => { const sh = new Shell(p9Fixture()); const r = sh.run(cmd); return r.out + r.err; };
const p9Shown = (log, cmd) => { const want = p9Out(cmd).trim(); return !!want && log.some(l => l.out.trim() === want); };
const P9_REC = T('הפלט הוקלט על שרת Ubuntu אמיתי. מה הודפס?', 'This was recorded on a real Ubuntu server. What was printed?');
const p9svc = (cmd, extra = []) => [cmd, `sudo ${cmd}`, ...extra];
